--correct typo
IF EXISTS (SELECT 1 FROM CODELKUP 
            WHERE LEFT(Long,4) = '2021'  AND  LISTNAME='FISCALMON' AND code2='2019Q4' AND StorerKey='LOGITECH' )
BEGIN
   UPDATE CODELKUP SET Long = REPLACE(Long,'2021','2019') 
                                        WHERE LISTNAME='FISCALMON' AND code2='2019Q4' AND StorerKey='LOGITECH'
END